"""Triton implementation of aten::conv_tbc (time-batch-channel 1-D convolution).

out[t, b, o] = bias[o] + sum_{k<K} sum_{c<Cin} self[t + k - pad, b, c] * weight[k, c, o]
with zero padding outside [0, T).

The problem is a GEMM over (M = Tout*B, Cout) with reduction depth K*C_in.
The output extent M and the channel extent Cout are compile-time constants so
the divisibility of the tile sizes is known at compile time: whenever
Cout % BLOCK_CO == 0 (or M % BLOCK_M == 0) the corresponding mask is dropped
from the weight loads and from the output store, which are the widest
elementwise tensors in the kernel.  The tap loop can be either fully unrolled
or a runtime loop that Triton can software-pipeline; a bounded autotune list
keeps both structures and several tile shapes available per shape.
"""

import torch
import triton
import triton.language as tl

from flag_gems.runtime import get_tuned_config

_CONFIGS = get_tuned_config("iluvatar_conv_tbc_candidate_0")


@triton.jit
def _acc_tap(
    acc,
    inp_ptr,
    w_ptr,
    arow,
    rmask,
    offs_o,
    o_mask,
    k,
    s_ic,
    s_wk,
    s_wc,
    s_wo,
    CIN: tl.constexpr,
    COUT: tl.constexpr,
    BLOCK_CO: tl.constexpr,
    BLOCK_CIN: tl.constexpr,
    IN_CONTIG: tl.constexpr,
    W_CONTIG: tl.constexpr,
    IP: tl.constexpr,
):
    for cb in tl.static_range((CIN + BLOCK_CIN - 1) // BLOCK_CIN):
        c = cb * BLOCK_CIN + tl.arange(0, BLOCK_CIN)
        if IN_CONTIG:
            a_ptrs = inp_ptr + arow[:, None] + c[None, :]
        else:
            a_ptrs = inp_ptr + arow[:, None] + c[None, :] * s_ic
        if CIN % BLOCK_CIN == 0:
            a = tl.load(a_ptrs, mask=rmask[:, None], other=0.0)
        else:
            a = tl.load(a_ptrs, mask=rmask[:, None] & (c[None, :] < CIN), other=0.0)

        if W_CONTIG:
            w_ptrs = w_ptr + k * CIN * COUT + c[:, None] * COUT + offs_o[None, :]
        else:
            w_ptrs = w_ptr + k * s_wk + c[:, None] * s_wc + offs_o[None, :] * s_wo
        if COUT % BLOCK_CO == 0:
            if CIN % BLOCK_CIN == 0:
                w = tl.load(w_ptrs)
            else:
                w = tl.load(w_ptrs, mask=c[:, None] < CIN, other=0.0)
        else:
            if CIN % BLOCK_CIN == 0:
                w = tl.load(w_ptrs, mask=o_mask[None, :], other=0.0)
            else:
                w = tl.load(
                    w_ptrs,
                    mask=(c[:, None] < CIN) & o_mask[None, :],
                    other=0.0,
                )

        acc = tl.dot(a, w, acc, input_precision=IP)
    return acc


@triton.autotune(configs=_CONFIGS, key=["T", "B", "pad", "dtag"])
@triton.jit
def _conv_tbc_kernel(
    inp_ptr,
    w_ptr,
    b_ptr,
    out_ptr,
    T,
    B,
    dtag,
    s_it,
    s_ib,
    s_ic,
    s_b,
    s_wk,
    s_wc,
    s_wo,
    s_ot,
    s_ob,
    s_oc,
    pad,
    CIN: tl.constexpr,
    COUT: tl.constexpr,
    K: tl.constexpr,
    M: tl.constexpr,
    HAS_BIAS: tl.constexpr,
    IN_CONTIG: tl.constexpr,
    W_CONTIG: tl.constexpr,
    O_CONTIG: tl.constexpr,
    IP: tl.constexpr,
    UNROLL: tl.constexpr,
    BLOCK_M: tl.constexpr,
    BLOCK_CO: tl.constexpr,
    BLOCK_CIN: tl.constexpr,
):
    tl.static_assert(CIN > 0)
    pid_m = tl.program_id(0)
    pid_o = tl.program_id(1)

    offs_m = pid_m * BLOCK_M + tl.arange(0, BLOCK_M)
    offs_o = pid_o * BLOCK_CO + tl.arange(0, BLOCK_CO)
    m_mask = offs_m < M
    o_mask = offs_o < COUT

    t = offs_m // B
    b = offs_m - t * B

    acc = tl.zeros((BLOCK_M, BLOCK_CO), dtype=tl.float32)

    # Loop-invariant bases: the tap loop only adds an affine k term.
    row_base = offs_m - pad * B
    t_base = t - pad
    TMAX = T * B

    if O_CONTIG:
        o_ptrs = out_ptr + offs_m[:, None] * COUT + offs_o[None, :]
    else:
        o_ptrs = out_ptr + (t * s_ot + b * s_ob)[:, None] + offs_o[None, :] * s_oc
    o_mask2 = m_mask[:, None] & o_mask[None, :]

    if UNROLL:
        for k in tl.static_range(K):
            if IN_CONTIG:
                row = row_base + k * B
                if M % BLOCK_M == 0:
                    rmask = (row >= 0) & (row < TMAX)
                else:
                    rmask = m_mask & (row >= 0) & (row < TMAX)
                arow = row * CIN
            else:
                t_in = t_base + k
                if M % BLOCK_M == 0:
                    rmask = (t_in >= 0) & (t_in < T)
                else:
                    rmask = m_mask & (t_in >= 0) & (t_in < T)
                arow = t_in * s_it + b * s_ib
            acc = _acc_tap(
                acc,
                inp_ptr,
                w_ptr,
                arow,
                rmask,
                offs_o,
                o_mask,
                k,
                s_ic,
                s_wk,
                s_wc,
                s_wo,
                CIN=CIN,
                COUT=COUT,
                BLOCK_CO=BLOCK_CO,
                BLOCK_CIN=BLOCK_CIN,
                IN_CONTIG=IN_CONTIG,
                W_CONTIG=W_CONTIG,
                IP=IP,
            )
    else:
        for k in tl.range(0, K):
            if IN_CONTIG:
                row = row_base + k * B
                if M % BLOCK_M == 0:
                    rmask = (row >= 0) & (row < TMAX)
                else:
                    rmask = m_mask & (row >= 0) & (row < TMAX)
                arow = row * CIN
            else:
                t_in = t_base + k
                if M % BLOCK_M == 0:
                    rmask = (t_in >= 0) & (t_in < T)
                else:
                    rmask = m_mask & (t_in >= 0) & (t_in < T)
                arow = t_in * s_it + b * s_ib
            acc = _acc_tap(
                acc,
                inp_ptr,
                w_ptr,
                arow,
                rmask,
                offs_o,
                o_mask,
                k,
                s_ic,
                s_wk,
                s_wc,
                s_wo,
                CIN=CIN,
                COUT=COUT,
                BLOCK_CO=BLOCK_CO,
                BLOCK_CIN=BLOCK_CIN,
                IN_CONTIG=IN_CONTIG,
                W_CONTIG=W_CONTIG,
                IP=IP,
            )

    if HAS_BIAS:
        if COUT % BLOCK_CO == 0:
            bias = tl.load(b_ptr + offs_o * s_b).to(tl.float32)
        else:
            bias = tl.load(b_ptr + offs_o * s_b, mask=o_mask, other=0.0).to(tl.float32)
        acc += bias[None, :]

    val = acc.to(out_ptr.dtype.element_ty)
    if COUT % BLOCK_CO == 0:
        if M % BLOCK_M == 0:
            tl.store(o_ptrs, val)
        else:
            tl.store(o_ptrs, val, mask=m_mask[:, None])
    else:
        tl.store(o_ptrs, val, mask=o_mask2)


_DTAG = {torch.float16: 0, torch.bfloat16: 1, torch.float32: 2}


def conv_tbc(self, weight, bias=None, pad=0, out=None):
    inp = self
    T, B, CIN = inp.shape
    K, cin_w, Cout = weight.shape
    Tout = T + 2 * pad - K + 1

    if out is None:
        out = torch.empty((Tout, B, Cout), dtype=inp.dtype, device=inp.device)

    if Tout <= 0 or B == 0 or Cout == 0 or CIN == 0 or K == 0:
        return out

    M = Tout * B

    s_it, s_ib, s_ic = inp.stride()
    s_wk, s_wc, s_wo = weight.stride()
    s_ot, s_ob, s_oc = out.stride()

    has_bias = bias is not None and bias.numel() > 0
    if has_bias:
        b_ptr = bias
        s_b = bias.stride(0)
    else:
        b_ptr = out
        s_b = 0

    ip = "ieee" if inp.dtype == torch.float32 else "tf32"
    dtag = _DTAG.get(inp.dtype, 3)

    grid = lambda meta: (
        triton.cdiv(M, meta["BLOCK_M"]),
        triton.cdiv(Cout, meta["BLOCK_CO"]),
    )
    _conv_tbc_kernel[grid](
        inp,
        weight,
        b_ptr,
        out,
        T,
        B,
        dtag,
        s_it,
        s_ib,
        s_ic,
        s_b,
        s_wk,
        s_wc,
        s_wo,
        s_ot,
        s_ob,
        s_oc,
        pad,
        CIN=CIN,
        COUT=Cout,
        K=K,
        M=M,
        HAS_BIAS=has_bias,
        IN_CONTIG=inp.is_contiguous(),
        W_CONTIG=weight.is_contiguous(),
        O_CONTIG=out.is_contiguous(),
        IP=ip,
    )
    return out
